using System;

namespace Rampage.Net
{
    /// <summary>
    /// 声明式 HTTP 客户端标注：标注本特性的接口在应用启动时由 DynamicHttpClientBuilder（Reflection.Emit）生成
    /// “接口名+Implementation” 动态实现类（继承 SuperHttpClient）并注册为服务
    /// Declarative HTTP client marker: an interface carrying this attribute gets an "interface-name+Implementation" dynamic class
    /// (deriving from SuperHttpClient) generated by DynamicHttpClientBuilder (Reflection.Emit) at startup and registered as a service
    /// </summary>
    /// <remarks>
    /// 接口方法签名硬约束：返回类型必须为 Task&lt;T&gt;，否则动态实现生成阶段直接抛出 NotSupportedException。
    /// Hard constraint on interface method signatures: the return type must be Task&lt;T&gt;; otherwise a NotSupportedException is thrown while generating the dynamic implementation.
    /// </remarks>
    [AttributeUsage(AttributeTargets.Interface)]
    public class SuperClientAttribute : Attribute
    {
        /// <summary>
        /// 客户端配置名：对应配置节 SuperHttpClients:Clients 中配置项的 Name；
        /// 缺省时以实现类类型名（动态生成类为“接口名+Implementation”）作为配置名查找
        /// The client config name matching the Name of an entry in the SuperHttpClients:Clients section;
        /// defaults to the implementation type name ("interface-name+Implementation" for generated classes) when absent
        /// </summary>
        public string? Name
        {
            get; set;
        }

        /// <summary>
        /// API 根地址（scheme + host[:port]，如 https://api.example.com）；缺省时回退到配置项的 Root
        /// The API root (scheme + host[:port], e.g. https://api.example.com); falls back to the config's Root when absent
        /// </summary>
        public string? Root
        {
            get; set;
        }

        /// <summary>
        /// 拦截器类型（须实现 <see cref="ISuperClientInterceptor"/>），加载配置时经 EmitTool 实例化并赋给客户端的 Interceptor
        /// The interceptor type (must implement <see cref="ISuperClientInterceptor"/>); instantiated via EmitTool during config loading and assigned to the client's Interceptor
        /// </summary>
        public Type? Handler
        {
            get; set;
        }

    }
}
